##  Processing a text file line by line

The chunks that are read from a response are not broken neatly at line
boundaries and are Uint8Arrays, not strings. If you want to fetch a text file
and process it line by line, it is up to you to handle these complications.
The following example shows one way to do this by creating a line iterator
(for simplicity, it assumes the text is UTF-8, and doesn't handle fetch
errors).

js



    async function* makeTextFileLineIterator(fileURL) {
      const utf8Decoder = new TextDecoder("utf-8");
      const response = await fetch(fileURL);
      const reader = response.body.getReader();
      let { value: chunk, done: readerDone } = await reader.read();
      chunk = chunk ? utf8Decoder.decode(chunk) : "";

      const newline = /\r?\n/gm;
      let startIndex = 0;
      let result;

      while (true) {
        const result = newline.exec(chunk);
        if (!result) {
          if (readerDone) break;
          const remainder = chunk.substr(startIndex);
          ({ value: chunk, done: readerDone } = await reader.read());
          chunk = remainder + (chunk ? utf8Decoder.decode(chunk) : "");
          startIndex = newline.lastIndex = 0;
          continue;
        }
        yield chunk.substring(startIndex, result.index);
        startIndex = newline.lastIndex;
      }

      if (startIndex < chunk.length) {
        // Last line didn't end in a newline char
        yield chunk.substr(startIndex);
      }
    }

    async function run() {
      for await (const line of makeTextFileLineIterator(urlOfFile)) {
        processLine(line);
      }
    }

    run();


