      const arr = desc.split(".");
      while (arr.length > 1) {
        obj = obj[arr.shift()];
      }
      return (obj[arr[0]] = value);
    }

    const obj = { a: { b: { c: 0 } } };
    const propPath = getPropPath(); // suppose it returns "a.b.c"
    const result = setDescendantProp(obj, propPath, 1); // obj.a.b.c is now 1


