ould be canceled, the ` condition ` callback should return a
literal ` false ` value or a promise that should resolve to ` false ` . If a
promise is returned, the thunk waits for it to get fulfilled before
dispatching the ` pending ` action, otherwise it proceeds with dispatching
synchronously.



    const fetchUserById = createAsyncThunk(  
      'users/fetchByIdStatus',  
      async (userId: number, thunkAPI) => {  
        const response = await userAPI.fetchById(userId)  
        return response.data  
      },  
      {  
        condition: (userId, { getState, extra }) => {  
          const { users } = getState()  
          const fetchStatus = users.requests[userId]  
          if (fetchStatus === 'fulfilled' || fetchStatus === 'loading') {  
            // Already fetched or in progress, don't need to re-fetch  
            return false  
          }  
        },  
      },  
    )  


If ` condition() ` returns ` false ` , the default behavior is that no actions
will be dispatched at all. If you still want a "rejected" action to be
dispatched when the thunk was canceled, pass in ` {condition,
dispatchConditionRejection: true} ` .

###  Canceling While Running  ​

If you want to cancel your running thunk before it has finished, you can use
the ` abort ` method of the promise returned by `
dispatch(fetchUserById(userId)) ` .

A real-life example of that would look like this:



    // file: store.ts noEmit  
    import { configureStore } from '@reduxjs/toolkit'  
    import type { Reducer } from '@reduxjs/toolkit'  
    import { useDispatch } from 'react-redux'  

    declare const reducer: Reducer<{}>  
    const store = configureStore({ reducer })  
    export const useAppDispatch = () => useDispatch<typeof store.dispatch>()  

    // file: slice.ts noEmit  
    import { createAsyncThunk } from '@reduxjs/toolkit'  
    export const fetchUserById = createAsyncThunk(  
      'fetchUserById',  
      (userId: string) => {  
        /* ... */  
      },  
    )  

    // file: MyComponent.ts  
    import { fetchUserById } from './slice'  
    import { useAppDispatch } from './store'  
    import React from 'react'  

    function MyComponent(props: { userId: string }) {  
      const dispatch = useAppDispatch()  
      React.useEffect(() => {  
        // Dispatching the thunk returns a promise  
        const promise = dispatch(fetchUserById(props.userId))  
        return () => {  
          // `createAsyncThunk` attaches an `abort()` method to the promise  
          promise.abort()  
        }  
      }, [props.userId])  
    }  


After a thunk has been cancelled this way, it will dispatch (and return) a `
"thunkName/rejected" ` action with an ` AbortError ` on the ` error `
property. The thunk will not dispatch any further actions.

Additionally, your ` payloadCreator ` can use the ` AbortSignal ` it is passed
via ` thunkAPI.signal ` to actually cancel a costly asynchronous action.

The ` fetch ` api of modern browsers already comes with support for an `
AbortSignal ` :



    import { createAsyncThunk } from '@reduxjs/toolkit'  

    const fetchUserById = createAsyncThunk(  
      'users/fetchById',  
      async (userId: string, thunkAPI) => {  
        const response = await fetch(`https://reqres.in/api/users/${userId}`, {  
          signal: thunkAPI.signal,  
        })  
        return await response.json()  
      },  
    )  


